import runpy,json,hashlib
from pathlib import Path
from datetime import datetime,timedelta
p=Path('output/qa/2026-11-13-agent-cost-rerun/round-02');ns=runpy.run_path(str(p/'capture_cost_progress.py'));db=ns['SessionLocal']();T=ns['text'];db.execute(T('SET TRANSACTION READ ONLY'))
r=dict(db.execute(T("SELECT id,status,started_at,finished_at,JSON_EXTRACT(run_context,'$.confirmation_wait_seconds') AS wait_seconds,JSON_UNQUOTE(JSON_EXTRACT(run_context,'$.deadline_at')) AS deadline_at FROM agent_runs WHERE id=61")).mappings().one());n=dict(db.execute(T("SELECT id,status,JSON_EXTRACT(sdk_state,'$.confirmation_wait_seconds') AS wait_seconds FROM agent_node_runs WHERE id=413")).mappings().one());a=dict(db.execute(T("SELECT id,status,JSON_UNQUOTE(JSON_EXTRACT(request_payload,'$.paused_at')) AS paused_at,decided_at FROM agent_approvals WHERE id=15")).mappings().one());assert not db.new and not db.dirty and not db.deleted;db.rollback();db.close()
old=json.loads((p/'resume/before-approval.json').read_text(encoding='utf8'));old_deadline=old['run_context']['deadline_at'];wait=float(r['wait_seconds']);assert wait==float(n['wait_seconds']);assert (datetime.fromisoformat(r['deadline_at'])-datetime.fromisoformat(old_deadline)).total_seconds()==wait
pause=datetime.fromisoformat(a['paused_at']);accounted_end=pause+timedelta(seconds=wait);wall=(r['finished_at']-r['started_at']).total_seconds();extra=(a['decided_at']-accounted_end).total_seconds();assert extra==17.293313
files=json.loads((p/'time-accounting-before-correction/manifest.json').read_text(encoding='utf8'))
for item in files:item['corrected_sha256']=hashlib.sha256((p/item['path']).read_bytes()).hexdigest()
report={'run_id':61,'correction_reason':'旧审计把稍后的approval.decided_at当人工等待结束点；apply_conflict_decision在入口接收now，先完成确认规则应用与检查点持久化，最后service才设置decided_at。因此旧算法误把17.293313秒服务端确认处理计为人工等待。','authoritative_evidence':{'run':r,'node':n,'approval':a,'deadline_before_confirmation':old_deadline,'deadline_after_confirmation':r['deadline_at'],'deadline_extension_seconds':wait},'corrected':{'run_wall_seconds':wall,'human_wait_seconds':wait,'active_execution_seconds':wall-wait,'pause_at_utc':pause.isoformat(),'runtime_wait_ended_at_utc_inferred_from_persisted_exact_elapsed':accounted_end.isoformat(),'approval_decided_at_utc':a['decided_at'].isoformat(),'confirmation_application_processing_seconds_previously_misclassified':extra,'post_wait_execution_wall_seconds':(r['finished_at']-accounted_end).total_seconds(),'whole_run_detailed_sdk_timing_complete':False},'superseded':{'human_wait_seconds':2909.704659,'active_execution_seconds':2132.295341,'post_approval_boundary':'approval.decided_at','post_approval_wall_seconds':1111.0,'post_approval_non_sdk_seconds':575.753671},'code_evidence':['conflict_confirmation.apply_conflict_decision: elapsed=now-paused_at; extends deadline and records confirmation_wait_seconds','service.decide_approval: apply_conflict_decision(now=datetime.utcnow()) before approval.decided_at=datetime.utcnow()'],'precision_limit':'Run.started_at/finished_at持久值精度为秒；微秒尾数来自完整等待量的相减，仅作核算派生，面向用户四舍五入到秒。','files':files,'raw_observation_preservation':'历史observations、资源JSONL和首次暂停原始记录保留，不改写旧采样；其active/human_wait派生字段以本报告更正。','model_requests_sent':0,'business_database_writes':0}
(p/'time-accounting-correction.json').write_text(json.dumps(report,ensure_ascii=False,indent=2,default=str),encoding='utf8');print(json.dumps(report['corrected'],ensure_ascii=False))
